/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python - <<'PY'
import json
import openai_client

captured = {}
class Response:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        pass
    def read(self):
        return json.dumps({\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}]}]}).encode()

def fake_urlopen(request, timeout):
    captured[\"payload\"] = json.loads(request.data)
    captured[\"authorization\"] = request.get_header(\"Authorization\")
    captured[\"timeout\"] = timeout
    return Response()

openai_client.urlopen = fake_urlopen
assert openai_client.send_prompt(\"private prompt\", api_key=\"test-key\") == \"hello\"
assert captured[\"payload\"][\"input\"] == \"private prompt\"
assert captured[\"payload\"][\"store\"] is False
assert captured[\"authorization\"] == \"Bearer test-key\"
print(\"mocked request checks passed\")
